---@overload fun(handle: ProjectItem, event: "interact", filter?: fun(event: PlayerInteractEvent): boolean): PlayerInteractEvent
---@overload fun(handle: ProjectItem, event: "interact_entity", filter?: fun(event: PlayerInteractEntityEvent): boolean): PlayerInteractEntityEvent
