---@field y number Up (+) and down (−).
---@field z number South (+) and north (−).
---@operator add(Vec3): Vec3
---@operator sub(Vec3): Vec3
---@operator unm: Vec3
---@operator mul(number): Vec3
---@operator mul(Vec3): Vec3
---@operator div(number): Vec3
local Vec3 = {}

--- How long it is.
---@return number
function Vec3:length() end

--- Its length squared: cheaper than `length()`, and enough for comparing distances.
---@return number
function Vec3:length_squared() end

--- The same direction with length 1. The zero vector stays zero rather than becoming NaN.
---@return Vec3
function Vec3:normalized() end

--- The dot product.
---@param other Vec3
---@return number
function Vec3:dot(other) end

--- The cross product: a vector at right angles to both, by the right-hand rule.
---@param other Vec3
---@return Vec3
function Vec3:cross(other) end

--- How far it is to another point.
---@param other Vec3
---@return number
function Vec3:distance(other) end

--- The distance squared: cheaper than `distance()`, and enough for comparing.
---@param other Vec3
---@return number
