--- A copy with `x` replaced.
---@param x number
---@return Vec3
function Vec3:with_x(x) end

--- A copy with `y` replaced.
---@param y number
---@return Vec3
function Vec3:with_y(y) end

--- A copy with `z` replaced.
---@param z number
---@return Vec3
function Vec3:with_z(z) end

--- Each component rounded down: the block a position is in.
---@return Vec3
function Vec3:floor() end

--- Each component rounded to the nearest whole number, halves up.
---@return Vec3
function Vec3:round() end

